'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], fmt=(x,n=2)=>Number(x).toFixed(n), short=id=>id.replace('CHEMBL238_Ki:','DAT-');
const names=['Set up','Predict','Select','Results','Learn'], keys=['setup','predict','select','results','learn'];
let DATA, rows=[], byId={}, selected=new Set(), compare=new Set(), active='', page='setup', tableTab='batch', filter='', budget=8, library='all', round=1, completed=0, batch=[], revealed={}, acquired={}, scoresBefore={}, learned=false, resultMode='replay', predicting=false, stage=0, progress=0, timer=null, cleanup=[], dialogCleanup=[], dialogView='properties';
const app=$('#app'),dialog=$('#compare-dialog');
const arrow='<span aria-hidden="true">↗</span>';
const proteinIcon='<svg viewBox="0 0 32 32"><path d="M7 5c22-4 14 18 3 12S7 2 19 7s11 21-2 19S2 15 12 13s15 2 13 10"/><circle cx="7" cy="5" r="2"/><circle cx="25" cy="23" r="2"/></svg>';
function pool(){return rows.filter(r=>!r.initial&&!(r.id in acquired)&&(library==='all'||r.similarity>=.35));}
function ranked(){return pool().sort((a,b)=>b.prediction-a.prediction||a.id.localeCompare(b.id));}
function picked(){return [...selected].map(id=>byId[id]).filter(Boolean).sort((a,b)=>b.prediction-a.prediction);}
function inspect(){return byId[active]||ranked()[0];}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function nav(){ $('#steps').innerHTML=names.map((name,i)=>`${i?'<span class="step-arrow" aria-hidden="true">›</span>':''}<button class="step ${page===keys[i]?'active':''} ${i<keys.indexOf(page)?'done':''}" data-step="${keys[i]}" ${page===keys[i]?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span>${name}</button>`).join('');$$('[data-step]').forEach(b=>b.onclick=()=>go(b.dataset.step));$('.brand>span:last-child').textContent=page==='setup'?'New campaign':`Dopamine transporter / Round ${round}`;}
function go(next){if(next==='predict'&&!fitPromise){startPrediction();return;}if(next==='select'&&learned){nextRound();return;}if(predicting&&next!=='predict'){clearInterval(timer);predicting=false;}if(next==='results'&&(!batch.length||batch.length!==selected.size||batch.some(c=>!selected.has(c.id)))){if(!selected.size){toast('Choose at least one compound first.');return;}freezeBatch();}if(next==='learn'&&!Object.keys(revealed).length){toast('Reveal or import the selected batch’s measurements first.');next='results';if(!batch.length)freezeBatch();}page=next;history.replaceState(null,'','#'+next);render();}
function render(){cleanup.forEach(f=>f());cleanup=[];nav();if(page==='setup')setup();if(page==='predict')predict();if(page==='select')selectPage();if(page==='results')results();if(page==='learn')learn();window.scrollTo(0,0);}
function setup(){app.innerHTML=`<div class="page"><div class="page-heading"><span class="eyebrow">A new discovery loop</span><h1>What do you want to discover?</h1><p>Choose the biological question, the compounds to explore, and how many you want to test. We’ll turn what you already know into a starting point.</p></div><div class="setup-grid"><div class="setup-left"><section class="section-card"><div class="section-label"><span>01</span><h3>Choose your target</h3></div><div class="target-field"><div class="target-icon">${proteinIcon}</div><div><strong>Human dopamine transporter</strong><small>SLC6A3 · DAT · Homo sapiens</small></div><select aria-label="Target protein"><option>DAT</option><option disabled>Other targets · next iteration</option></select></div><p class="target-note">The protein your compounds may bind to. This prototype uses the verified DAT public dataset.</p><div class="setting-row"><span>What are we predicting?</span><span class="badge purple">Binding potency · pKᵢ</span></div><p class="target-note">Higher pKᵢ means stronger measured binding in this assay. Protein structure is optional context; the current model learns from molecular fingerprints and known measurements.</p></section><section class="section-card"><div class="section-label"><span>02</span><h3>Choose your compound library</h3></div><div class="choice-row"><button class="choice ${library==='all'?'active':''}" data-library="all"><span class="check">${library==='all'?'✓':''}</span><strong>Explore the full library</strong><small>All ${rows.filter(r=>!r.initial&&!(r.id in acquired)).length} available compounds</small></button><button class="choice ${library==='near'?'active':''}" data-library="near"><span class="check">${library==='near'?'✓':''}</span><strong>Stay near known chemistry</strong><small>Similarity ≥ 0.35 to measured compounds</small></button></div><div class="count-strip"><div><strong>${32+Object.keys(acquired).length}</strong><span>known measurements</span></div><div><strong>${pool().length}</strong><span>compounds to score</span></div><div><strong>1</strong><span>consistent assay</span></div></div><div class="file-row"><span>↳</span> Public DAT dataset · source structures and measurements</div></section><section class="section-card"><div class="section-label"><span>03</span><h3>Set the size of your next step</h3></div><div class="setting-row" style="margin-top:0"><span>Compounds in this batch</span><div class="stepper"><button id="budget-down" aria-label="Decrease batch size">−</button><input id="budget" type="number" min="1" max="16" value="${budget}" aria-label="Batch size"><button id="budget-up" aria-label="Increase batch size">+</button></div></div><p class="target-note">Start with the highest predictions, then make the final selection yourself.</p></section></div><aside><div class="protein-card"><canvas id="setup-protein" aria-label="Rotating experimental DAT protein backbone"></canvas><span class="protein-tag">STRUCTURAL CONTEXT / 8Y2G</span><div class="protein-bottom"><span>Experimental protein backbone</span><span>Drag to rotate ↔</span></div></div><div class="summary-card"><h3>Your campaign, at a glance</h3><div class="summary-line"><span>Target</span><span>Human DAT</span></div><div class="summary-line"><span>Prediction</span><span>Binding potency, pKᵢ</span></div><div class="summary-line"><span>Model</span><span>Morgan + ridge</span></div><div class="summary-line"><span>Batch size</span><span>${budget} compounds</span></div><div class="summary-note"><span>◷</span><span><strong>No lab? Start with a replay.</strong><br>Choose a batch, reveal its existing public measurements, and watch the model learn. No new experiment is implied.</span></div></div></aside></div><div class="setup-actions"><small>Sandbox only. Your current campaigns stay untouched.</small><button class="btn primary" id="start-predict">Start predicting <span>→</span></button></div><div class="setup-bottom"><span>◇</span> Public data · local computation · no cloud or laboratory connection</div></div>`;
$$('[data-library]').forEach(b=>b.onclick=()=>{library=b.dataset.library;selected=new Set(ranked().slice(0,budget).map(r=>r.id));render();});
function setBudget(n){budget=Math.max(1,Math.min(16,Number(n)||8,pool().length));selected=new Set(ranked().slice(0,budget).map(r=>r.id));render();}
$('#budget').onchange=e=>setBudget(e.target.value);$('#budget-down').onclick=()=>setBudget(budget-1);$('#budget-up').onclick=()=>setBudget(budget+1);$('#start-predict').onclick=startPrediction;cleanup.push(molecularCanvas($('#setup-protein'),null,'overview'));}
const stages=[['Read the evidence','Known compounds and assay measurements'],['Encode the chemistry','Molecular structures → fingerprint features'],['Fit the relationship','Learn from the observed measurements'],['Score the candidates','Estimate pKᵢ for untested compounds'],['Prepare your shortlist','Rank predictions for your review']];
function predict(){app.innerHTML=`<section class="predict-page"><div class="predict-heading"><div><span class="eyebrow">Round ${round} / Predict</span><h1>${stage===5?'A starting point. The choice is yours.':'From known chemistry to new possibilities.'}</h1><p>Human DAT · ${32+Object.keys(acquired).length} measurements · ${pool().length} candidate compounds</p></div><span class="badge purple">Morgan + ridge</span></div><div class="predict-layout"><div class="process-list">${stages.map((s,i)=>`<div class="process-step ${i===Math.min(stage,4)?'active':''} ${i<stage?'complete':''}" data-stage="${i}"><span>${i<stage?'✓':i+1}</span><div><strong>${s[0]}</strong><small>${s[1]}</small></div></div>`).join('')}</div><div class="thinking-scene"><canvas id="thinking-canvas" aria-label="Animated view of encoding, model fitting and scoring"></canvas><div class="scene-caption" id="scene-caption">CHEMICAL STRUCTURES → MOLECULAR FEATURES → PREDICTIONS</div></div><aside class="process-readout"><span id="readout-label">OBSERVED EVIDENCE</span><div class="readout-number" id="readout-number">${32+Object.keys(acquired).length}</div><p id="readout-text">Measurements provide the starting signal.</p><div class="signal-bars">${[18,31,22,45,29,39,50,36,25,43,32,18].map((h,i)=>`<i style="height:${h}px;animation-delay:${i*.13}s"></i>`).join('')}</div><div class="readout-footer">Human DAT · one assay · pKᵢ</div></aside></div><div class="predict-footer"><div class="progress-track"><i id="progress" style="width:${progress}%"></i></div><div class="between"><span id="progress-label">${stage===5?'Ready to review your candidates':'Following the prediction workflow…'}</span><div class="flex"><button class="btn small" id="skip-animation">${stage===5?'Replay animation':'Skip animation'}</button><button class="btn primary" id="review-candidates" ${stage<5?'disabled':''}>Select compounds →</button></div></div><p class="playback-note">Step-by-step animation, not a measure of compute time. Predictions come from a real local fit; molecular motion is illustrative.</p></div></section>`;$('#skip-animation').onclick=()=>stage===5?startPrediction():finishPrediction();$('#review-candidates').onclick=()=>go('select');cleanup.push(thinkingCanvas($('#thinking-canvas')));updateStage();}
let fitPromise=null;
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await r.json();if(!r.ok)throw Error(value.error||'Request failed');return value;}
function startPrediction(){stage=0;progress=0;predicting=true;page='predict';render();fitPromise=request('/api/score',{ids:Object.keys(acquired),observations:acquired});fitPromise.catch(()=>{});clearInterval(timer);let ticks=0;timer=setInterval(()=>{ticks++;progress=Math.min(94,ticks*2);stage=Math.min(4,Math.floor(ticks/9));updateStage();if(ticks>=45)finishPrediction();},180);}
function updateStage(){if(page!=='predict')return;$$('[data-stage]').forEach((el,i)=>{el.classList.toggle('active',i===Math.min(stage,4));el.classList.toggle('complete',i<stage);el.firstElementChild.textContent=i<stage?'✓':i+1;});if($('#progress'))$('#progress').style.width=progress+'%';const readouts=[['OBSERVED EVIDENCE',32+Object.keys(acquired).length,'Known assay results. Nothing from the unmeasured pool is used for fitting.'],['STRUCTURAL ENCODING','2,048','Fingerprint bits describe chemical environments. The protein coordinates are not model inputs.'],['FITTING THE MODEL','ridge','Training-only scaling and a regularized regression fit to observed pKᵢ.'],['CANDIDATES SCORED',pool().length,'Every available compound receives an estimated binding potency.'],['STARTING SHORTLIST',budget,'Highest predictions first. You can swap, compare, and decide.'],['READY FOR REVIEW',pool().length,'Inspect the evidence and build the batch you want to test.']];const r=readouts[stage];$('#readout-label').textContent=r[0];$('#readout-number').textContent=r[1];$('#readout-text').textContent=r[2];if(stage===5){$('#progress-label').textContent='Scoring complete. Your candidate workspace is ready.';$('#review-candidates').disabled=false;$('#skip-animation').textContent='Replay animation';$('.predict-heading h1').textContent='A starting point. The choice is yours.';}}
async function finishPrediction(){clearInterval(timer);const pending=fitPromise;try{const result=await pending;if(pending!==fitPromise||page!=='predict')return;result.scores.forEach(s=>Object.assign(byId[s.id],s));selected=new Set(ranked().slice(0,budget).map(r=>r.id));active=ranked()[0]?.id||'';stage=5;progress=100;predicting=false;updateStage();}catch(e){predicting=false;toast(e.message);if(page!=='predict')return;$('#progress-label').textContent='Could not fit the model. Retry the walkthrough.';$('#skip-animation').textContent='Retry';$('#skip-animation').onclick=startPrediction;}}
function plotSvg(){const w=820,h=440,left=68,right=21,top=24,bottom=55,min=3,max=10;const x=v=>left+(v-min)/(max-min)*(w-left-right),y=v=>h-bottom-v*(h-top-bottom);const c=inspect();let html=`<svg viewBox="0 0 ${w} ${h}" role="group" aria-label="Candidate map. Horizontal: predicted pKi. Vertical: novelty relative to measured chemistry.">`;
for(let t=3;t<=10;t++)html+=`<line x1="${x(t)}" x2="${x(t)}" y1="${top}" y2="${h-bottom}" stroke="#e9e7eb"/><text x="${x(t)}" y="${h-bottom+23}" text-anchor="middle" fill="#88848f" font-size="11" font-family="monospace">${t}.0</text>`;
for(let t=0;t<=1.01;t+=.25)html+=`<line x1="${left}" x2="${w-right}" y1="${y(t)}" y2="${y(t)}" stroke="#e9e7eb"/><text x="${left-12}" y="${y(t)+4}" text-anchor="end" fill="#88848f" font-size="11" font-family="monospace">${t.toFixed(2)}</text>`;
html+=`<rect x="${left}" y="${top}" width="${w-left-right}" height="${h-top-bottom}" fill="none" stroke="#d8d4dc"/><text x="${left}" y="${h-8}" font-size="11" fill="#64606e" font-family="monospace">Predicted pKᵢ → stronger binding</text><text transform="translate(17 ${h/2}) rotate(-90)" text-anchor="middle" font-size="11" fill="#64606e" font-family="monospace">Novelty → farther from measured chemistry</text>`;
rows.filter(r=>r.initial||r.id in acquired).forEach(r=>{const value=r.initial?r.value:acquired[r.id];html+=`<rect x="${x(value)-3}" y="${y(0)-3}" width="6" height="6" fill="#56535d"><title>${r.short}: observed ${fmt(value)} pKi</title></rect>`;});
if(c)html+=`<path d="M${left} ${y(1-c.similarity)}H${x(c.prediction)}V${h-bottom}" fill="none" stroke="#b9a6ed" stroke-dasharray="3 4"/>`;
const ordered=[...pool().filter(r=>r.id!==active),...(c?[c]:[])];ordered.forEach(r=>{const is=selected.has(r.id),on=r.id===active;html+=`<g class="plot-point" data-point="${r.id}" tabindex="0" role="button" aria-label="Inspect ${r.short}, predicted pKi ${fmt(r.prediction)}${is?', in batch':''}"><title>${r.short} · predicted ${fmt(r.prediction)} · similarity ${fmt(r.similarity)}</title>${on?`<circle cx="${x(r.prediction)}" cy="${y(1-r.similarity)}" r="13" fill="#e9e0ff"/>`:''}<circle cx="${x(r.prediction)}" cy="${y(1-r.similarity)}" r="${on?6.5:is?6:3.3}" fill="${on?'#6441d8':is?'white':'#bdbac5'}" stroke="${is||on?'#6441d8':'none'}" stroke-width="1.8"/>${on?`<rect x="${Math.min(x(r.prediction)+17,w-105)}" y="${y(1-r.similarity)-12}" width="79" height="24" rx="4" fill="white" stroke="#ddd7e7"/><text x="${Math.min(x(r.prediction)+26,w-96)}" y="${y(1-r.similarity)+4}" font-size="10" fill="#514665" font-family="monospace">${r.short}</text>`:''}</g>`;});return html+'</svg>';}
function selectPage(){if(!active||!pool().some(r=>r.id===active))active=ranked()[0]?.id||'';const c=inspect();if(!c){app.innerHTML='<div class="page"><h1>Every compound has a measurement.</h1><p>Your public replay is complete.</p><button class="btn" onclick="location.reload()">Restart prototype</button></div>';return;}
app.innerHTML=`<section class="selection-shell"><div class="selection-toolbar"><h2>Human DAT <span>/ Round ${round} · Choose your next batch</span></h2><div class="flex"><span class="toolbar-note">Your judgment, supported by the model.</span><button class="btn small" id="auto-pick">Restore top ${budget}</button><button class="btn small ${compare.size?'soft':''}" id="compare-open">Compare <span>${compare.size?`(${compare.size})`:'compounds'}</span></button></div></div><div class="selection-main"><section class="map-panel"><div class="between panel-top"><h3>Candidate map</h3><span>${pool().length} untested · ${32+Object.keys(acquired).length} measured</span></div><div class="legend"><span><i class="dot"></i> Untested</span><span><i class="dot square"></i> Measured</span><span><i class="dot outline"></i> In your batch</span></div><div class="plot-wrap">${plotSvg()}</div><div class="plot-foot">Select a point to inspect it. Novelty is chemical distance, not calibrated uncertainty.</div></section><aside class="inspector"><div class="between"><span class="overline">${selected.has(c.id)?'In your batch':'Inspecting candidate'} · ${selected.size} selected</span><span class="badge ${selected.has(c.id)?'purple':''}">${selected.has(c.id)?'Selected':'Available'}</span></div><h2>${c.short}</h2><div class="molecule-box"><img src="${c.image}" alt="Chemical structure of ${c.short}"><div class="descriptors"><span>MW ${fmt(c.mw,1)}</span><span>cLogP ${fmt(c.logp)}</span><span>TPSA ${fmt(c.tpsa,1)}</span></div></div><div class="inspector-score"><span>Predicted pKᵢ</span><div><strong>${fmt(c.prediction)}</strong><span class="score-meter"><i style="left:${Math.max(0,Math.min(95,(c.prediction-3)/7*100))}%"></i></span></div><span>Nearest measured</span><small>${short(c.nearest)} · sim ${fmt(c.similarity)}<br>Observed ${fmt(c.nearest_value)} pKᵢ</small></div><div class="rationale"><h4>What the evidence says</h4><p>${c.prediction>=ranked()[Math.min(7,ranked().length-1)].prediction?'One of the strongest model predictions in this pool.':'A candidate you can consider alongside the model’s top picks.'} Its nearest measured compound shares ${Math.round(c.similarity*100)}% fingerprint similarity. Inspect its structure before adding it to your batch.</p></div><div class="inspector-actions"><button class="btn ${selected.has(c.id)?'soft':'primary'}" id="toggle-batch">${selected.has(c.id)?'✓ In batch · remove':'+ Add to batch'}</button><button class="btn" id="compare-toggle">${compare.has(c.id)?'✓ Comparing':'+ Compare'}</button><button class="btn" id="open-dock">Explore 3D ${arrow}</button></div></aside></div><section class="batch-panel"><div class="batch-toolbar"><div class="table-tabs"><button data-tab="batch" class="${tableTab==='batch'?'active':''}">Your batch <span>${selected.size}</span></button><button data-tab="all" class="${tableTab==='all'?'active':''}">All candidates <span>${pool().length}</span></button></div><input class="table-search" id="candidate-search" aria-label="Find a candidate" placeholder="Find a compound…" value="${filter.replaceAll('"','&quot;')}"></div><div class="table-scroll" id="candidate-table"></div></section><footer class="selection-footer"><span>${selected.size} of ${budget} slots selected · Round ${round}</span><div class="flex"><button class="btn small" id="back-setup">Edit settings</button><button class="btn primary" id="confirm-batch" ${selected.size===0?'disabled':''}>Continue with ${selected.size} compounds →</button></div></footer></section>${compare.size?`<div class="compare-tray"><span>${[...compare].map(short).join(' · ')}</span><button class="btn soft small" id="tray-open">Compare →</button><button id="clear-compare" aria-label="Clear comparison">×</button></div>`:''}`;
$$('[data-point]').forEach(el=>{el.onclick=()=>{active=el.dataset.point;selectPage();};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick();}};});$('#toggle-batch').onclick=()=>toggleBatch(c.id);$('#compare-toggle').onclick=()=>{if(compare.has(c.id))compare.delete(c.id);else if(compare.size<3)compare.add(c.id);else toast('Compare up to three compounds at a time.');selectPage();};$('#compare-open').onclick=()=>openCompare();$('#open-dock').onclick=()=>{compare=new Set([c.id]);openCompare('docking');};$('#auto-pick').onclick=()=>{selected=new Set(ranked().slice(0,budget).map(r=>r.id));selectPage();};$('#confirm-batch').onclick=()=>{freezeBatch();go('results');};$('#back-setup').onclick=()=>go('setup');$$('[data-tab]').forEach(b=>b.onclick=()=>{tableTab=b.dataset.tab;selectPage();});$('#candidate-search').oninput=e=>{filter=e.target.value;renderTable();};if($('#tray-open')){$('#tray-open').onclick=()=>openCompare();$('#clear-compare').onclick=()=>{compare.clear();selectPage();};}renderTable();}
function toggleBatch(id){if(selected.has(id))selected.delete(id);else if(selected.size<budget)selected.add(id);else{toast(`Your ${budget}-compound batch is full. Remove one or increase the batch size in settings.`);return;}selectPage();}
function renderTable(){const items=(tableTab==='batch'?picked():ranked()).filter(r=>r.short.toLowerCase().includes(filter.toLowerCase())||r.id.toLowerCase().includes(filter.toLowerCase()));$('#candidate-table').innerHTML=items.length?`<table><thead><tr><th>Select</th><th>Compound</th><th>Predicted pKᵢ</th><th>Nearest similarity</th><th>Evidence</th><th>Compare</th></tr></thead><tbody>${items.map(r=>`<tr data-row="${r.id}" class="${r.id===active?'inspected':''}"><td><input type="checkbox" aria-label="Select ${r.short}" data-check="${r.id}" ${selected.has(r.id)?'checked':''}></td><td><strong class="mono">${r.short}</strong></td><td class="mono">${fmt(r.prediction)}<span class="table-mini-bar"><i style="width:${Math.max(0,Math.min(100,(r.prediction-3)/7*100))}%"></i></span></td><td class="mono">${fmt(r.similarity)}</td><td class="muted">${DATA.poses[r.id]?'Saved 3D pose available':'Measured analog available'}</td><td><button class="btn small" data-compare="${r.id}">${compare.has(r.id)?'✓ Added':'+ Compare'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty-table">No compounds here yet. Choose candidates from the map or the full library.</div>';
$$('[data-row]').forEach(el=>el.onclick=()=>{active=el.dataset.row;selectPage();});$$('[data-check]').forEach(el=>el.onclick=e=>{e.stopPropagation();toggleBatch(el.dataset.check);});$$('[data-compare]').forEach(el=>el.onclick=e=>{e.stopPropagation();const id=el.dataset.compare;if(compare.has(id))compare.delete(id);else if(compare.size<3)compare.add(id);else toast('Compare up to three compounds.');selectPage();});}
function freezeBatch(){batch=picked().map(c=>({...c}));revealed={};learned=false;scoresBefore=Object.fromEntries(pool().map(c=>[c.id,c.prediction]));}
function results(){const ready=batch.length&&batch.every(c=>c.id in revealed);app.innerHTML=`<div class="page"><div class="page-heading"><span class="eyebrow">Round ${round} / Results</span><h1>${ready?'The observations are in.':'A batch chosen. What happens next?'}</h1><p>${ready?'Compare what the model expected with what was measured. Surprises are useful—they tell the next fit something new.':'You don’t need a lab to explore the loop. Replay existing measurements now, or preview how real assay results would come back later.'}</p></div><div class="results-layout"><section class="results-card"><div class="results-card-header between"><h3>Your ${batch.length}-compound batch</h3><span class="badge ${ready?'green':''}">${ready?'Measurements revealed':'Awaiting observations'}</span></div><div class="table-scroll"><table><thead><tr><th>Compound</th><th>Structure</th><th>Predicted pKᵢ</th><th>Observed pKᵢ</th><th>Difference</th></tr></thead><tbody>${batch.map(c=>`<tr class="result-row"><td class="mono">${c.short}</td><td><img src="${c.image}" alt="${c.short} structure"></td><td class="result-value">${fmt(c.prediction)}</td><td class="result-value ${c.id in revealed?'':'blur-value'}">${c.id in revealed?fmt(revealed[c.id]):'— —'}</td><td>${c.id in revealed?`<span class="delta ${revealed[c.id]>=c.prediction?'positive':'negative'}">${revealed[c.id]>=c.prediction?'+':''}${fmt(revealed[c.id]-c.prediction)}</span>`:'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div><div class="result-summary"><div><strong>${Object.keys(revealed).length}/${batch.length}</strong><small>measurements received</small></div><div><strong>${ready?fmt(batch.reduce((s,c)=>s+Math.abs(c.prediction-revealed[c.id]),0)/batch.length):'—'}</strong><small>batch mean absolute error</small></div></div></section><aside><div class="results-controls"><button data-mode="replay" class="${resultMode==='replay'?'active':''}">Public-data replay</button><button data-mode="lab" class="${resultMode==='lab'?'active':''}">Lab workflow</button></div>${resultMode==='replay'?`<div class="replay-card"><div class="replay-glyph">${ready?'✓':'▷'}</div><h3>${ready?'Existing measurements, revealed.':'Try the full loop, without a lab.'}</h3><p>These compounds already have published measurements. Reveal the values for your selected batch to simulate receiving an assay result.</p><button class="btn primary" id="reveal" ${ready?'disabled':''}>${ready?'Measurements received':'Reveal public measurements'} ${ready?'✓':'→'}</button><small>Retrospective replay · no new experiments performed</small></div>`:`<div class="replay-card"><h3>When you have lab results</h3><p>Export the selected compound IDs, then return a CSV with <span class="mono">compound_id,value</span>. Values must already be pKᵢ. Imports stay in this prototype session.</p><button class="btn" id="export-batch">↓ Export result template</button><div class="file-drop" style="margin-top:16px">Preview a result import<input id="result-upload" type="file" accept=".csv" aria-label="Import result CSV"></div><div id="import-error" class="lab-error" role="alert"></div></div>`}<div class="neutral-note"><strong>The handoff to a real lab</strong>Keep the same flow: select → export → measure externally → import. Aster records observations; it does not run the assay or order compounds.</div></aside></div><div class="results-actions"><button class="btn" id="edit-batch">← Back to selection</button><button class="btn primary" id="go-learn" ${!ready?'disabled':''}>Learn from these results →</button></div></div>`;$$('[data-mode]').forEach(b=>b.onclick=()=>{resultMode=b.dataset.mode;results();});if($('#reveal'))$('#reveal').onclick=async()=>{const b=$('#reveal');b.disabled=true;b.textContent='Revealing measurements…';try{const r=await request('/api/reveal',{ids:batch.map(c=>c.id)});revealed=r.outcomes;results();}catch(e){toast(e.message);b.disabled=false;}};if($('#export-batch'))$('#export-batch').onclick=exportBatch;if($('#result-upload'))$('#result-upload').onchange=importResults;$('#edit-batch').onclick=()=>go('select');$('#go-learn').onclick=()=>go('learn');}
function exportBatch(){download('aster-round-'+round+'.csv','compound_id,value\n'+batch.map(c=>c.id+',').join('\n'),'text/csv');}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
async function importResults(e){try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('Use a small result CSV under 100 KB.');const lines=(await file.text()).trim().split(/\r?\n/);if(lines.shift().trim()!=='compound_id,value')throw Error('Use the columns compound_id,value in that order.');const values={};for(const line of lines){const [id,raw,...extra]=line.split(',');if(extra.length||!batch.some(c=>c.id===id)||raw===undefined||raw.trim()===''||!Number.isFinite(Number(raw))||id in values)throw Error('Each row needs one unique selected compound ID and a finite pKi value.');values[id]=Number(raw);}if(Object.keys(values).length!==batch.length)throw Error('This prototype expects one result for every selected compound.');revealed=values;results();toast('Results loaded into this prototype session only.');}catch(error){$('#import-error').textContent=error.message;}}
function learn(){const mae=batch.reduce((s,c)=>s+Math.abs(c.prediction-revealed[c.id]),0)/batch.length;const observations=32+Object.keys(acquired).length+(learned?0:batch.length);app.innerHTML=`<div class="page"><div class="page-heading"><span class="eyebrow">Round ${round} / Learn</span><h1>Every result changes what comes next.</h1><p>The goal isn’t to make every prediction look right. It’s to use the new evidence to make a better-informed next decision.</p></div><div class="learning-metrics"><div class="metric-card"><span>New observations</span><strong>+${batch.length}</strong><small>${observations} measurements available for the next fit</small></div><div class="metric-card"><span>Batch prediction error</span><strong>${fmt(mae)}</strong><small>Mean absolute error · pKᵢ units</small></div><div class="metric-card"><span>Still to explore</span><strong>${pool().length-(learned?0:batch.length)}</strong><small>Compounds without revealed measurements</small></div></div><div class="learn-layout"><section class="section-card"><div class="between"><h3>Expectation meets observation</h3><span class="badge">This selected batch only</span></div><div class="learn-chart">${outcomeChart()}</div><p class="muted" style="font-size:10px">The diagonal marks a perfect match. This selected batch is not an independent model-quality benchmark.</p></section><section class="section-card"><h3>${learned?'How the remaining predictions changed':'What the next fit will use'}</h3>${learned?changesHTML():`<div class="learning-note"><strong style="color:var(--ink)">${32+Object.keys(acquired).length} known + ${batch.length} newly revealed measurements</strong><br>The model is fitted again from the accumulated observations. Only measured outcomes are used; the remaining candidates are rescored.</div><div class="summary-line"><span>Model</span><span>Morgan + ridge</span></div><div class="summary-line"><span>Protein coordinates</span><span>Context only</span></div><div class="summary-line"><span>Selection</span><span>You remain in control</span></div>`}<div class="learning-note">${learned?'A changed prediction is not proof of a better model. The next batch tests the updated estimates.':'More data can change the ranking in either direction. The workflow preserves those changes so you can inspect them.'}</div></section></div><div class="learn-ready"><div><h3>${learned?'Ready for your next discovery loop.':'Close the loop with a new fit.'}</h3><p>${learned?'The remaining compounds now have updated predictions. Review the next shortlist.':'Fit locally using the new observations, then inspect what changed.'}</p></div><button class="btn primary" id="refit">${learned?'Select the next batch →':'Update the model →'}</button></div></div>`;$('#refit').onclick=learned?nextRound:refit;}
function outcomeChart(){const values=batch.flatMap(c=>[c.prediction,revealed[c.id]]),min=Math.floor(Math.min(4,...values)),max=Math.ceil(Math.max(10,...values)),x=v=>45+(v-min)/(max-min)*430,y=v=>250-(v-min)/(max-min)*215;let s='<svg viewBox="0 0 510 295" role="img" aria-label="Predicted versus observed pKi for the selected batch">';for(let i=min;i<=max;i+=Math.max(1,Math.ceil((max-min)/4)))s+=`<path d="M${x(i)} 25V250M45 ${y(i)}H475" stroke="#eeeaf3"/><text x="${x(i)}" y="271" text-anchor="middle" fill="#9992a4" font-size="10">${i}</text><text x="30" y="${y(i)+3}" text-anchor="end" fill="#9992a4" font-size="10">${i}</text>`;s+='<path d="M45 250L475 35" stroke="#b4a1df" stroke-dasharray="4 5"/>';batch.forEach(c=>s+=`<circle cx="${x(c.prediction)}" cy="${y(revealed[c.id])}" r="5" fill="#7655d4"><title>${c.short}: predicted ${fmt(c.prediction)}, observed ${fmt(revealed[c.id])}</title></circle>`);return s+'<text x="240" y="292" text-anchor="middle" fill="#8d8599" font-size="10">Predicted pKᵢ</text><text transform="translate(12 140) rotate(-90)" text-anchor="middle" fill="#8d8599" font-size="10">Observed pKᵢ</text></svg>';}
function changesHTML(){const changes=pool().filter(c=>c.id in scoresBefore).sort((a,b)=>Math.abs(b.prediction-scoresBefore[b.id])-Math.abs(a.prediction-scoresBefore[a.id])).slice(0,5);return changes.map(c=>`<div class="rank-change"><strong>${c.short}</strong><span class="muted mono">${fmt(scoresBefore[c.id])} → ${fmt(c.prediction)}</span><span>${c.prediction>=scoresBefore[c.id]?'+':''}${fmt(c.prediction-scoresBefore[c.id])}</span></div>`).join('');}
async function refit(){const b=$('#refit');b.disabled=true;b.textContent='Fitting from the new observations…';try{const observations={...acquired,...revealed};const r=await request('/api/score',{ids:Object.keys(observations),observations});acquired=observations;r.scores.forEach(s=>Object.assign(byId[s.id],s));learned=true;completed=round;learn();}catch(e){toast(e.message);b.disabled=false;b.textContent='Try fitting again';}}
function nextRound(){round++;batch=[];revealed={};learned=false;selected=new Set(ranked().slice(0,budget).map(c=>c.id));active=ranked()[0]?.id||'';compare.clear();go('select');toast('New predictions, new choices. Your next batch is ready to review.');}
function clearDialog(){dialogCleanup.forEach(f=>f());dialogCleanup=[];}
dialog.addEventListener('close',clearDialog);
function openCompare(view='properties'){
 dialogView=view;clearDialog();
 const ids=compare.size?[...compare]:[active];
 const items=ids.map(id=>byId[id]).filter(Boolean);
 $('#dialog-content').innerHTML=`<div class="dialog-header"><div><span class="eyebrow">Inspect the evidence</span><h2 id="dialog-title">Compare compounds</h2></div><button class="btn" id="close-dialog" aria-label="Close comparison">✕</button></div><div class="dialog-tabs"><button data-view="properties" class="${view==='properties'?'active':''}">Properties</button><button data-view="docking" class="${view==='docking'?'active':''}">3D docking</button></div><div class="compare-grid" style="--columns:${items.length}">${items.map((c,i)=>`<section class="comparison-card"><h3>${c.short}</h3>${view==='properties'?`<img src="${c.image}" alt="${c.short} molecular structure" style="width:100%"><div class="summary-line"><span>Predicted pKᵢ</span><strong>${fmt(c.prediction)}</strong></div><div class="summary-line"><span>Molecular weight</span><span>${fmt(c.mw,1)}</span></div><div class="summary-line"><span>cLogP / TPSA</span><span>${fmt(c.logp,1)} / ${fmt(c.tpsa,1)}</span></div><div class="summary-line"><span>Nearest measured similarity</span><span>${fmt(c.similarity)}</span></div>`:`<canvas class="docking-canvas" id="pose-${i}" aria-label="Interactive DAT binding pocket and ${DATA.poses[c.id]?'predicted ligand pose':'experimental reference'}"></canvas><div class="docking-legend">Violet: experimental reference · Gold: predicted pose</div>${DATA.poses[c.id]?`<div class="pose-controls"><label>Saved pose <select data-pose="${i}">${DATA.poses[c.id].map((p,j)=>`<option value="${j}">Pose ${p.rank} · ${fmt(p.score)} kcal/mol</option>`).join('')}</select></label></div>`:'<p class="no-pose">No saved docking pose for this compound. Showing the experimental reference only.</p>'}`}</section>`).join('')}</div>${view==='docking'?`<div class="dialog-note">Drag to rotate · Scroll to zoom. Experimental DAT structure: 8Y2G. Saved Vina poses are structural hypotheses; docking scores are not binding measurements.<div style="margin-top:12px">Explore compounds with saved poses: ${Object.keys(DATA.poses).map(id=>`<button class="btn small" data-example="${id}">${short(id)}</button>`).join(' ')}</div></div>`:'<div class="dialog-note">Compare up to three compounds using the comparison buttons in the selection table. Predictions are estimates, not measured outcomes.</div>'}`;
 $('#close-dialog').onclick=()=>dialog.close();$$('[data-view]').forEach(b=>b.onclick=()=>openCompare(b.dataset.view));
 $$('[data-example]').forEach(b=>b.onclick=()=>{compare.add(b.dataset.example);if(compare.size>3)compare.delete([...compare][0]);openCompare('docking');});
 if(view==='docking')items.forEach((c,i)=>{let stop=molecularCanvas($('#pose-'+i),DATA.poses[c.id]?.[0],'pocket');dialogCleanup.push(()=>stop());const select=$(`[data-pose="${i}"]`);if(select)select.onchange=()=>{stop();stop=molecularCanvas($('#pose-'+i),DATA.poses[c.id][Number(select.value)],'pocket');};});
 if(!dialog.open)dialog.showModal();
}
function molecularCanvas(canvas,pose,mode){
 const ctx=canvas.getContext('2d'),structure=DATA.structure;let yaw=.4,pitch=.2,zoom=1,drag=null,frame,dead=false;
 const overview=mode==='overview',points=overview?structure.ca:structure.pocket;
 const center=overview?[0,1,2].map(i=>points.reduce((s,p)=>s+p[i],0)/points.length):structure.center;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function project(p){let x=p[0]-center[0],y=p[1]-center[1],z=p[2]-center[2];const a=x*Math.cos(yaw)+z*Math.sin(yaw),b=-x*Math.sin(yaw)+z*Math.cos(yaw),v=y*Math.cos(pitch)-b*Math.sin(pitch);return [canvas.clientWidth/2+a*scale,canvas.clientHeight/2-v*scale,b];}
 let scale=1;
 function ligand(m,color){if(!m)return;ctx.strokeStyle=color;ctx.lineWidth=2;for(const [a,b]of m.bonds){const p=project(m.atoms[a]),q=project(m.atoms[b]);ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();}for(const a of m.atoms){if(a[3]==='H')continue;const p=project(a);ctx.fillStyle=({O:'#db6d70',N:'#678dce',Cl:'#74a782',F:'#74a782'})[a[3]]||color;ctx.beginPath();ctx.arc(p[0],p[1],3.5,0,Math.PI*2);ctx.fill();}}
 function draw(){if(dead)return;const w=canvas.clientWidth,h=canvas.clientHeight,dpr=Math.min(devicePixelRatio,2);if(canvas.width!==w*dpr||canvas.height!==h*dpr){canvas.width=w*dpr;canvas.height=h*dpr;}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);scale=Math.min(w,h)/(overview?85:30)*zoom;if(!drag&&!reduced)yaw+=.0016;
 if(overview){ctx.lineWidth=3;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];if(Math.hypot(...a.map((v,j)=>v-b[j]))>6)continue;const p=project(a),q=project(b);ctx.strokeStyle=`hsla(${250+i/points.length*30},40%,${60+p[2]/4}%,.7)`;ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.stroke();}}else{for(const a of points){const p=project(a);ctx.fillStyle='rgba(153,143,171,.22)';ctx.beginPath();ctx.arc(p[0],p[1],2.2,0,Math.PI*2);ctx.fill();}ligand(structure.reference,'#9064d8');ligand(pose,'#d4a13a');}
 frame=requestAnimationFrame(draw);}
 canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY];canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(drag){yaw+=(e.clientX-drag[0])*.01;pitch+=(e.clientY-drag[1])*.01;drag=[e.clientX,e.clientY];}};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;const wheel=e=>{e.preventDefault();zoom=Math.max(.5,Math.min(3,zoom*Math.exp(-e.deltaY*.001)));};canvas.addEventListener('wheel',wheel,{passive:false});draw();return()=>{dead=true;cancelAnimationFrame(frame);canvas.removeEventListener('wheel',wheel);canvas.onpointerdown=canvas.onpointermove=canvas.onpointerup=canvas.onpointercancel=null;};
}
function thinkingCanvas(canvas){const ctx=canvas.getContext('2d');let frame,t=0,dead=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;function draw(){if(dead)return;const w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(devicePixelRatio,2);canvas.width=w*d;canvas.height=h*d;ctx.scale(d,d);if(!reduced)t+=.014;const centers=[w*.17,w*.5,w*.83],cy=h*.48;ctx.font='10px monospace';ctx.textAlign='center';['CHEMISTRY','FINGERPRINTS','PREDICTIONS'].forEach((s,i)=>{ctx.fillStyle='#8c829d';ctx.fillText(s,centers[i],h*.83);});ctx.strokeStyle='#e4dcef';for(let i=0;i<2;i++){ctx.beginPath();ctx.moveTo(centers[i]+35,cy);ctx.lineTo(centers[i+1]-35,cy);ctx.stroke();for(let j=0;j<4;j++){const k=(t*.22+j/4)%1;ctx.fillStyle='#ad91e8';ctx.beginPath();ctx.arc(centers[i]+35+k*(centers[i+1]-centers[i]-70),cy,2,0,7);ctx.fill();}}
 for(let k=0;k<5;k++){const cx=centers[0]+Math.sin(k*2)*18,yy=cy+(k-2)*34;ctx.strokeStyle=k===stage?'#7954d3':'#bbb0cf';ctx.lineWidth=1.5;ctx.beginPath();for(let j=0;j<=6;j++){const a=j*Math.PI/3;const x=cx+15*Math.cos(a),y=yy+15*Math.sin(a);j?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}
 for(let i=0;i<10;i++)for(let j=0;j<10;j++){ctx.fillStyle=(i*7+j*13+Math.floor(t*2))%5<2?'#9b7bd9':'#eee9f6';ctx.fillRect(centers[1]-44+i*9,cy-44+j*9,6,6);}
 for(let i=0;i<7;i++){const yy=cy-65+i*21,len=20+(7-i)*5;ctx.fillStyle=i<3?'#8a66d5':'#d7cbe9';ctx.fillRect(centers[2]-30,yy,len,5);ctx.beginPath();ctx.arc(centers[2]-39,yy+2.5,3,0,7);ctx.fill();}frame=requestAnimationFrame(draw);}draw();return()=>{dead=true;cancelAnimationFrame(frame);};}
$('.brand').onclick=e=>{e.preventDefault();go('setup');};
$('#prototype-info').onclick=()=>{clearDialog();$('#dialog-content').innerHTML='<div class="dialog-header"><h2 id="dialog-title">A separate workflow prototype</h2><button class="btn" id="close-dialog">Close</button></div><div class="dialog-note">Your existing application and campaigns are unchanged. This sandbox uses public DAT compounds, local Morgan/ridge predictions, experimental 8Y2G coordinates, and saved docking poses. Results can be replayed from public measurements or imported for this browser session. Reloading resets the session.</div>';$('#close-dialog').onclick=()=>dialog.close();dialog.showModal();};
fetch('data.json').then(r=>r.json()).then(data=>{DATA=data;rows=data.compounds;byId=Object.fromEntries(rows.map(r=>[r.id,r]));selected=new Set(ranked().slice(0,budget).map(r=>r.id));active=ranked()[0]?.id;render();}).catch(e=>{app.textContent='Unable to load the prototype: '+e.message;});
